(8928,'enUS','Have you had any luck finding the imp in Darkwhisper Gorge?',0),
(8938,'enUS','You\'re ready to perform the exchange?',0),
(8940,'enUS','You\'re ready to perform the exchange?',0),
(8946,'enUS','Ysida... is she alive?',0),
